"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[345],{1345:(e,t,a)=>{a.d(t,{L:()=>r,N:()=>i});let o="Perseus Digital Library 원문, CC BY-SA 3.0. 한국어는 이 사이트의 자체 번역.",i=["전체","직접 인용","동일 사건의 외부 기록","동시대 제도 자료","문화적 평행","문학적 모방설"],r=[{id:"josephus-agrippa-death",actsReference:"행 12:20-23",eventIds:["a04-11"],relation:"동일 사건의 외부 기록",title:"신으로 불린 아그립바의 죽음",author:"플라비우스 요세푸스",work:"『유대 고대사』",citation:"19.344-346",date:"약 AD 93-94 기록",language:"고대 그리스어",lang:"grc",lead:"요세푸스도 가이사랴의 축제에서 아그립바가 신으로 불린 뒤 심한 통증을 겪었다고 기록한다.",lines:[{locator:"\xa7344",original:"δευτέρᾳ δὴ τῶν θεωριῶν ἡμέρᾳ στολὴν ἐνδὺς ἐξ ἀργύρου πεποιημένην πᾶσαν, ὡς θαυμάσιον ὑφὴν εἶναι, παρῆλθεν εἰς τὸ θέατρον ἀρχομένης ἡμέρας. ἔνθα ταῖς πρώταις τῶν ἡλιακῶν ἀκτίνων ἐπιβολαῖς ὁ ἄργυρος καταυγασθεὶς θαυμασίως ἀπέστιλβε μαρμαίρων τι φοβερὸν καὶ τοῖς εἰς αὐτὸν ἀτενίζουσι φρικῶδες.",translation:"공연 둘째 날, 그는 놀라운 직조물인 순은제 의복을 입고 날이 밝기 시작할 때 극장에 들어왔다. 은이 첫 햇살을 받아 놀랍게 빛나자, 그를 바라보는 이들에게 두렵고 오싹한 인상을 주었다."},{locator:"\xa7345",original:"εὐθὺς δὲ οἱ κόλακες τὰς οὐδὲ ἐκείνῳ πρὸς ἀγαθοῦ ἄλλος ἄλλοθεν φωνὰς ἀνεβόων, θεὸν προσαγορεύοντες εὐμενής τε εἴης ἐπιλέγοντες, ‘εἰ καὶ μέχρι νῦν ὡς ἄνθρωπον ἐφοβήθημεν,’",translation:"곧 아첨꾼들이 사방에서 그에게 이롭지 않은 말들을 외치며 그를 신이라고 불렀다. 그들은 ‘우리에게 자비로우소서. 지금까지는 당신을 인간으로 두려워했지만’이라고 말했다."},{locator:"\xa7346",original:"‘ἀλλὰ τοὐντεῦθεν κρείττονά σε θνητῆς φύσεως ὁμολογοῦμεν.’ οὐκ ἐπέπληξεν τούτοις ὁ βασιλεὺς οὐδὲ τὴν κολακείαν ἀσεβοῦσαν ἀπετρίψατο. ἀνακύψας δ᾽ οὖν μετ᾽ ὀλίγον τὸν βουβῶνα τῆς ἑαυτοῦ κεφαλῆς ὑπερκαθιζόμενον εἶδεν ἐπὶ σχοινίου τινός. ἄγγελον τοῦτον εὐθὺς ἐνόησεν κακῶν εἶναι τὸν καί ποτε τῶν ἀγαθῶν γενόμενον, καὶ διακάρδιον ἔσχεν ὀδύνην, ἄθρουν δ᾽ αὐτῷ τῆς κοιλίας προσέφυσεν ἄλγημα μετὰ σφοδρότητος ἀρξάμενον.",translation:"‘이제부터는 당신이 죽을 인간의 본성보다 뛰어나다고 고백합니다.’ 왕은 이들을 꾸짖지도, 불경한 아첨을 물리치지도 않았다. 잠시 뒤 고개를 들어 자기 머리 위 밧줄에 앉은 부엉이를 보았다. 그는 전에 좋은 소식을 전했던 그것이 이제 불행의 사자임을 깨달았고, 마음 깊이 고통스러워했다. 갑자기 배에 격렬한 통증이 일어났다."}],connection:"사도행전과 요세푸스는 아그립바 1세, 가이사랴, 신적 환호, 갑작스러운 죽음을 함께 전한다. 두 기록을 나란히 보면 누가가 권력자의 죽음을 하나님의 심판과 말씀의 성장이라는 서사 안에 배치한 방식이 더 분명해진다.",caution:"두 기록의 세부는 다르다. 사도행전은 주의 사자와 벌레를 말하고, 요세푸스는 빛나는 의복, 부엉이의 징조, 복통과 닷새 뒤의 죽음을 전한다. 요세푸스의 기록을 사도행전의 직접 자료로 간주할 근거는 없다.",edition:"B. Niese 편, Flavii Iosephi opera, Berlin: Weidmann, 1892",license:o,sources:[{label:"Perseus 그리스어 원문",url:"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0145%3Abook%3D19%3Asection%3D344&lang=original"},{label:"Perseus 영역과 대조",url:"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0146%3Abook%3D19%3Asection%3D343"}],keywords:["헤롯","아그립바","가이사랴","신","죽음","요세푸스"]},{id:"josephus-egyptian-prophet",actsReference:"행 21:37-39",eventIds:["a09-04"],relation:"동일 사건의 외부 기록",title:"감람산으로 무리를 이끈 이집트인 예언자",author:"플라비우스 요세푸스",work:"『유대 전쟁사』",citation:"2.261-263",date:"약 AD 75-79 기록",language:"고대 그리스어",lang:"grc",lead:"천부장은 바울을 이집트인 반란 지도자로 오인한다. 요세푸스는 이 인물을 벨릭스 시대의 거짓 예언자로 기록한다.",lines:[{locator:"\xa7261",original:"Μείζονι δὲ τούτου πληγῇ Ἰουδαίους ἐκάκωσεν ὁ Αἰγύπτιος ψευδοπροφήτης: παραγενόμενος γὰρ εἰς τὴν χώραν ἄνθρωπος γόης καὶ προφήτου πίστιν ἐπιθεὶς ἑαυτῷ περὶ τρισμυρίους μὲν ἀθροίζει τῶν ἠπατημένων,",translation:"이보다 더 큰 타격으로 유대인들을 해친 자는 이집트인 거짓 예언자였다. 그는 그 땅에 들어온 협잡꾼으로, 자신이 예언자라는 신뢰를 얻어 속은 사람 약 삼만 명을 모았다."},{locator:"\xa7262",original:"περιαγαγὼν δὲ αὐτοὺς ἐκ τῆς ἐρημίας εἰς τὸ ἐλαιῶν καλούμενον ὄρος ἐκεῖθεν οἷός τε ἦν εἰς Ἱεροσόλυμα παρελθεῖν βιάζεσθαι καὶ κρατήσας τῆς τε Ῥωμαϊκῆς φρουρᾶς καὶ τοῦ δήμου τυραννεῖν χρώμενος τοῖς συνεισπεσοῦσιν δορυφόροις.",translation:"그는 이들을 광야에서 이끌어 감람산이라 불리는 산으로 데려갔다. 거기서 예루살렘에 강제로 들어가 로마 수비대와 민중을 장악하고, 함께 돌입한 무장 호위대를 이용해 지배하려 했다."},{locator:"\xa7263",original:"φθάνει δ᾽ αὐτοῦ τὴν ὁρμὴν Φῆλιξ ὑπαντήσας μετὰ τῶν Ῥωμαϊκῶν ὁπλιτῶν, καὶ πᾶς ὁ δῆμος συνεφήψατο τῆς ἀμύνης, ὥστε συμβολῆς γενομένης τὸν μὲν Αἰγύπτιον φυγεῖν μετ᾽ ὀλίγων, διαφθαρῆναι δὲ καὶ ζωγρηθῆναι πλείστους τῶν σὺν αὐτῷ, τὸ δὲ λοιπὸν πλῆθος σκεδασθὲν ἐπὶ τὴν ἑαυτῶν ἕκαστον διαλαθεῖν.",translation:"그러나 벨릭스가 로마 중무장 병사들과 맞서 그의 시도를 먼저 막았고, 온 민중도 방어에 가담했다. 충돌이 일어나자 이집트인은 몇 사람과 함께 달아났고, 그와 함께한 이들 가운데 많은 사람이 죽거나 붙잡혔다. 나머지는 흩어져 각자 숨어들었다."}],connection:"두 기록 모두 이집트 출신 지도자가 광야로 추종자들을 이끈 일을 전한다. 감람산과 벨릭스 군대의 진압, 지도자의 도주는 요세푸스가 덧붙이는 정보다. 행 21:38의 천부장 질문은 바울을 그 지도자와 혼동한 이유를 드러낸다.",caution:"사도행전은 자객 사천 명을, 『유대 전쟁사』는 속은 사람 약 삼만 명을 말한다. 수치와 집단 묘사는 일치하지 않으므로 어느 한 기록으로 다른 기록을 단순 교정해서는 안 된다.",edition:"B. Niese 편, Flavii Iosephi opera, Berlin: Weidmann, 1895",license:o,sources:[{label:"Perseus 그리스어 원문",url:"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0147%3Abook%3D2%3Asection%3D261&lang=original"},{label:"『유대 고대사』의 병행 기록",url:"https://www.perseus.tufts.edu/hopper/text?doc=J.+AJ+20.8&lang=original"}],keywords:["이집트인","애굽인","감람산","벨릭스","반란","요세푸스"]},{id:"aratus-offspring",actsReference:"행 17:22-31",eventIds:["a07-07"],relation:"직접 인용",title:"우리 또한 그의 자손이다",author:"아라투스",work:"『파이노메나』",citation:"1-5행",date:"기원전 3세기 전반",language:"고대 그리스어",lang:"grc",lead:"아레오바고 연설의 ‘우리도 그의 소생이라’는 말은 아라투스 5행과 직접 겹친다.",lines:[{locator:"1-4행",original:"Ἐκ Διὸς ἀρχώμεσθα, τὸν οὐδέποτ᾽ ἄνδρες ἐῶμεν ἄρρητον\xb7 μεσταὶ δὲ Διὸς πᾶσαι μὲν ἀγυιαί, πᾶσαι δ᾽ ἀνθρώπων ἀγοραί, μεστὴ δὲ θάλασσα καὶ λιμένες\xb7 πάντη δὲ Διὸς κεχρήμεθα πάντες.",translation:"제우스에게서 시작하자. 사람들은 결코 그를 말하지 않은 채 두지 않는다. 모든 거리와 인간의 모든 시장이 제우스로 가득하고, 바다와 항구도 가득하다. 어디서나 우리 모두는 제우스를 필요로 한다."},{locator:"5행",original:"τοῦ γὰρ καὶ γένος εἰμέν.",translation:"우리 또한 그의 자손이기 때문이다."}],connection:"바울은 청중에게 익숙한 시구를 인용해, 사람이 하늘과 땅을 지으신 하나님께 속한다고 설명한다. 아라투스의 시에서 이 구절은 제우스를 가리킨다. 인용은 연설의 접점이지만 결론은 우상 비판, 회개, 심판과 부활로 나아간다.",caution:"행 17:28 후반과 아라투스 5행의 언어적 일치는 분명하다. 그러나 앞부분 ‘우리가 그를 힘입어 살며 움직이며 존재한다’의 정확한 문헌 출처는 이 항목에서 확정하지 않는다.",edition:"G. R. Mair 편, Aratus: Phaenomena, London and New York, 1921",license:o,sources:[{label:"Perseus 그리스어 원문",url:"https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:2008.01.0483"},{label:"Perseus 판본 정보",url:"https://catalog.perseus.org/catalog/urn:cts:greekLit:tlg0653.tlg001"}],keywords:["아레오바고","아라투스","시인","인용","소생","자손","제우스"]},{id:"gallio-delphi-inscription",actsReference:"행 18:12-17",eventIds:["a07-08b"],relation:"동시대 제도 자료",title:"아가야 총독 갈리오",author:"클라우디우스 황제의 델포이 칙서",work:"갈리오 비문",citation:"SIG\xb3 801d, 6행",date:"약 AD 52",language:"고대 그리스어",lang:"grc",lead:"델포이에서 발견된 비문은 갈리오를 아가야의 총독으로 부르며 사도행전의 행정 명칭과 일치한다.",lines:[{locator:"6행, 복원",original:"καθὼς Λούκιος Ἰούνιος Γαλλίων ὁ φίλος μου καὶ ἀνθύπατος τῆς Ἀχαΐας ἔγραψεν",translation:"나의 벗이며 아가야의 총독인 루키우스 유니우스 갈리오가 내게 보고한 바에 따르면"}],connection:"비문의 ‘아가야의 총독’과 행 18:12의 직함이 일치한다. 클라우디우스의 칙서를 연대 측정에 사용하면 바울의 고린도 체류를 1세기 중반의 로마 행정 일정 안에 놓을 수 있다.",caution:"비문은 파편 아홉 조각을 이어 복원한 문서이며, 바울이나 고린도의 재판을 언급하지 않는다. 이 자료가 확인하는 것은 갈리오의 이름, 직위와 대략적인 재임 시기다.",edition:"델포이 비문 파편, Fouilles de Delphes III.4, no. 286; SIG\xb3 801d",license:"고대 비문 원문을 통상적인 복원문으로 제시하고 한국어는 이 사이트에서 번역함.",sources:[{label:"K. C. Hanson 전사와 비문 사진",url:"https://kchanson.com/ANCDOCS/greek/gallio.html"},{label:"A. Plassart의 비문 연구",url:"https://doi.org/10.3406/reg.1967.3963"}],keywords:["갈리오","고린도","아가야","총독","비문","델포이","연대"]},{id:"ovid-baucis-philemon",actsReference:"행 14:8-18",eventIds:["a05-07"],relation:"문화적 평행",title:"여행자의 모습으로 찾아온 두 신",author:"오비디우스",work:"『변신 이야기』",citation:"8.626-634",date:"약 AD 8",language:"라틴어",lang:"la",lead:"유피테르와 메르쿠리우스가 인간의 모습으로 집들을 찾아다니는 이야기는 루스드라 주민들의 반응을 이해할 비교 자료가 된다.",lines:[{locator:"626-629행",original:"Iuppiter huc specie mortali cumque parente venit Atlantiades positis caducifer alis. Mille domos adiere locum requiemque petentes, mille domos clausere serae.",translation:"유피테르는 인간의 모습을 하고 이곳에 왔다. 아틀라스의 후손인 지팡이를 든 이도 날개를 내려놓고 아버지와 함께 왔다. 그들은 쉴 곳을 구하며 천 채의 집을 찾았으나, 천 채의 집마다 빗장이 닫혔다."},{locator:"630-634행",original:"Tamen una recepit, parva quidem, stipulis et canna tecta palustri; sed pia Baucis anus parilique aetate Philemon illa sunt annis iuncti iuvenalibus, illa consenuere casa paupertatemque fatendo effecere levem nec iniqua mente ferendo.",translation:"그러나 작은 집 하나가 그들을 맞아들였다. 그 집은 볏짚과 늪의 갈대로 지붕을 이은 곳이었다. 경건한 노인 바우키스와 비슷한 나이의 필레몬은 젊을 때 결혼해 그 오두막에서 함께 늙었다. 두 사람은 가난을 인정하고 불평 없이 견디어 그 짐을 가볍게 만들었다."}],connection:"행 14장에서 루스드라 사람들은 바나바를 제우스, 바울을 헤르메스로 부르고 제사를 드리려 한다. 오비디우스의 이야기는 신들이 인간 여행자의 모습으로 방문할 수 있다는 제국기 문학의 익숙한 상상과 환대의 주제를 보여 준다.",caution:"오비디우스의 이야기는 브루기아를 배경으로 하고, 사도행전의 사건은 루가오니아의 루스드라에서 일어난다. 누가가 이 작품을 직접 사용했다거나 루스드라 주민들이 바로 이 이야기를 떠올렸다고 단정할 수 없다.",edition:"Hugo Magnus 편, Ovid: Metamorphoses, Gotha: Friedr. Andr. Perthes, 1892",license:o,sources:[{label:"Perseus 라틴어 원문",url:"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.02.0029%3Abook%3D8%3Acard%3D612"}],keywords:["루스드라","제우스","헤르메스","유피테르","메르쿠리우스","환대","오비디우스"]},{id:"homer-elpenor-eutychus",actsReference:"행 20:7-12",eventIds:["a08-06"],relation:"문학적 모방설",title:"지붕에서 떨어진 엘페노르",author:"호메로스",work:"『오디세이』",citation:"10.552-560",date:"전승상 기원전 8-7세기",language:"고대 그리스어",lang:"grc",lead:"엘페노르와 유두고는 모두 높은 곳에서 잠들었다가 떨어진 젊은이지만, 두 이야기의 결말은 정반대다.",lines:[{locator:"552-555행",original:"Ἐλπήνωρ δέ τις ἔσκε νεώτατος, οὔτε τι λίην ἄλκιμος ἐν πολέμῳ οὔτε φρεσὶν ᾗσιν ἀρηρώς\xb7 ὅς μοι ἄνευθ᾽ ἑτάρων ἱεροῖς ἐν δώμασι Κίρκης, ψύχεος ἱμείρων, κατελέξατο οἰνοβαρείων.",translation:"엘페노르라는 이가 있었는데 가장 젊었고, 전투에서 그리 용맹하지도 자기 생각이 단단하지도 않았다. 그는 동료들과 떨어져 키르케의 신성한 집에서 시원한 곳을 찾다가 술에 짓눌린 채 누웠다."},{locator:"556-560행",original:"κινυμένων δ᾽ ἑτάρων ὅμαδον καὶ δοῦπον ἀκούσας ἐξαπίνης ἀνόρουσε καὶ ἐκλάθετο φρεσὶν ᾗσιν ἄψορρον καταβῆναι ἰὼν ἐς κλίμακα μακρήν, ἀλλὰ καταντικρὺ τέγεος πέσεν\xb7 ἐκ δέ οἱ αὐχὴν ἀστραγάλων ἐάγη, ψυχὴ δ᾽ Ἄϊδόσδε κατῆλθεν.",translation:"동료들이 움직이는 소리와 발소리를 듣자 그는 갑자기 일어났다. 긴 사다리로 되돌아가 내려가야 한다는 것을 잊고 지붕에서 곧장 떨어졌다. 목뼈가 부러졌고 그의 혼은 하데스로 내려갔다."}],connection:"두 이야기에는 젊은이가 높은 곳에서 잠들었다가 추락한다는 공통점이 있다. 엘페노르는 술에 취해 자다가 동료들의 움직임에 놀라 떨어지고, 유두고는 바울의 긴 강론을 듣다가 깊이 잠든다. 모방설을 따르는 해석은 엘페노르의 죽음과 유두고의 생명 회복을 대비해 읽는다.",caution:"이 연결은 명시적 인용이 아니라 문학적 모방설이다. 유두고 사건은 엘리야와 엘리사의 소생 이야기와도 연결되며, 높은 곳에서 잠든 사람이 추락하는 공통 모티프만으로 직접 의존을 증명할 수는 없다.",edition:"A. T. Murray 편, Homer: Odyssey, Cambridge, MA: Harvard University Press, 1919",license:o,sources:[{label:"Perseus 그리스어 원문",url:"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0135%3Abook%3D10%3Acard%3D552&lang=original"},{label:"D. R. MacDonald의 모방설 서지",url:"https://brill.com/previewpdf/book/edcoll/9789004236219/B9789004236219-s018.xml"},{label:"고대 서사 영향에 대한 비판적 검토",url:"https://era.ed.ac.uk/bitstream/1842/8759/2/Adams2011.pdf"}],keywords:["유두고","드로아","엘페노르","호메로스","추락","죽음","소생","모방"]}]}}]);